import csv,statistics as st,datetime as dt,collections as C
def rd(f): return list(csv.DictReader(open(f)))
I=rd('incidents.csv');A={r['incident_id']:r for r in rd('activity.csv')}
P=lambda s:dt.datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ')
rows=[]
for r in I:
    a=A.get(r['incident_id']);o=P(r['opened_at'])
    r=dict(r);r['o']=o;r['post']=int(o>=dt.datetime(2026,6,8))
    if a:
        r['ttc']=(P(a['closed_at'])-o).total_seconds()/3600;r['rm']=float(a['responder_minutes']);r['ho']=int(a['handoffs']);r['re']=int(a['reopened_within_72h'])
    else: r['ttc']=r['rm']=r['ho']=r['re']=None
    rows.append(r)
def med(x):x=[v for v in x if v is not None];return st.median(x) if x else float('nan')
def mean(x):x=[v for v in x if v is not None];return st.mean(x) if x else float('nan')
EOF
