print('no activity',C.Counter((r['post'],r['severity']) for r in rows if r['ttc'] is None))
print('neg ttc',sum(1 for r in rows if r['ttc'] is not None and r['ttc']<0))
for k in ['severity','intake_channel','service_group']:
    print(k,{p:dict(sorted(C.Counter(r[k] for r in rows if r['post']==p).items())) for p in (0,1)})
def summ(rs):
    return f"n={len(rs)} closed={sum(r['ttc'] is not None for r in rs)} medTTC={med([r['ttc'] for r in rs]):.2f} meanTTC={mean([r['ttc'] for r in rs]):.2f} medRM={med([r['rm'] for r in rs]):.0f} meanRM={mean([r['rm'] for r in rs]):.1f} ho={mean([r['ho'] for r in rs]):.2f} reopen={mean([r['re'] for r in rs]):.3f}"
for p in (0,1): print('post',p,summ([r for r in rows if r['post']==p]))
for s in ['sev1','sev2','sev3']:
    for p in (0,1): print(s,p,summ([r for r in rows if r['post']==p and r['severity']==s]))
for k in ['service_group','intake_channel']:
  for v in sorted({r[k] for r in rows}):
    for p in (0,1): print(v,p,summ([r for r in rows if r['post']==p and r[k]==v]))
